// The lines of an env file made from apps/api/env.example (generated by
// tools/env-example.mjs): `KEY=value` is set, `# KEY=value` is an optional
// variable shown with its default, and a comment block above a variable that
// holds the line `# Required.` marks it as one the app cannot start without.
// Pure functions on text; setup.mjs and check.mjs do the file work.

const KEY = /^(#\s*)?([A-Z][A-Z0-9_]*)=(.*)$/;

/** The variables of the text: { key, active, value, line, required }. */
export function parseEnv(text) {
  const found = [];
  let required = false;
  text.split('\n').forEach((line, index) => {
    const m = KEY.exec(line);
    if (m) {
      found.push({
        key: m[2],
        active: !m[1],
        value: m[3],
        line: index,
        required,
      });
      required = false;
    } else if (line.trim() === '# Required.') {
      required = true;
    } else if (!line.startsWith('#')) {
      required = false;
    }
  });
  return found;
}

/** The value of an active, non-empty variable; undefined otherwise. */
export function valueOf(text, key) {
  const v = parseEnv(text).find((e) => e.key === key && e.active);
  return v && v.value !== '' ? v.value : undefined;
}

/**
 * The text with `key` set to `value`: its active line is replaced, else its
 * commented example is activated. Null when the text does not name the key.
 */
export function setValue(text, key, value) {
  const lines = text.split('\n');
  const entries = parseEnv(text).filter((e) => e.key === key);
  const entry = entries.find((e) => e.active) ?? entries[0];
  if (!entry) return null;
  lines[entry.line] = `${key}=${value}`;
  return lines.join('\n');
}

/**
 * Findings of a file against its template: the REQUIRED variables unset,
 * the variables the template does not name, the ones set twice.
 */
export function compare(templateText, fileText) {
  const template = parseEnv(templateText);
  const named = new Set(template.map((e) => e.key));
  const file = parseEnv(fileText).filter((e) => e.active);
  const counts = new Map();
  for (const e of file) counts.set(e.key, (counts.get(e.key) ?? 0) + 1);
  return {
    empty: [
      ...new Set(template.filter((e) => e.required).map((e) => e.key)),
    ].filter((key) => valueOf(fileText, key) === undefined),
    unknown: [...new Set(file.map((e) => e.key))].filter(
      (key) => !named.has(key),
    ),
    repeated: [...counts].filter(([, n]) => n > 1).map(([key]) => key),
  };
}
